const raw = String($env.WATCH_TARGET_URLS || 'https://example.com,https://status.example.com');
const targets = raw
  .split(',')
  .map((u) => u.trim())
  .filter((u) => u.startsWith('https://') || u.startsWith('http://'));
const maxLatencyMs = Number($env.WATCH_MAX_LATENCY_MS || 2500);
const pricePattern = String($env.WATCH_PRICE_REGEX || '').trim();
const expectedPrice = String($env.WATCH_EXPECTED_PRICE || '').trim();
const minSslDays = Number($env.WATCH_SSL_MIN_DAYS || 14);

return targets.map((url) => ({
  json: {
    url,
    maxLatencyMs,
    pricePattern,
    expectedPrice,
    minSslDays,
    checkedAt: new Date().toISOString(),
    startedMs: Date.now()
  }
}));

const items = $input.all();
const srcItems = $('Load Monitored URLs').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const resp = items[i].json || {};
  const meta = srcItems[i]?.json || {};
  const statusCode = Number(resp.statusCode || 0);
  const elapsedMs = Math.max(1, Date.now() - Number(meta.startedMs || Date.now()));
  const headers = resp.headers || {};
  const bodyStr = typeof resp.body === 'string' ? resp.body : JSON.stringify(resp.body || '');
  const errorMsg = String(resp.error?.message || resp.error || '');
  const reasons = [];

  if (statusCode < 200 || statusCode >= 400) {
    const detail = errorMsg ? `${statusCode || 'ERR'} (${errorMsg.slice(0, 120)})` : String(statusCode || 'TIMEOUT / TLS ERROR');
    reasons.push(`HTTP error: ${detail}`);
  }
  if (elapsedMs > Number(meta.maxLatencyMs || 2500)) {
    reasons.push(`High latency: ${elapsedMs}ms > ${meta.maxLatencyMs}ms`);
  }
  if (meta.url && meta.url.startsWith('http://')) {
    reasons.push('HTTPS/TLS not enabled (plain http:// URL)');
  }
  const sslDaysHeader = headers['x-ssl-expiry-days'] ?? headers['X-SSL-Expiry-Days'];
  if (sslDaysHeader !== undefined && sslDaysHeader !== '') {
    const sslDays = Number(sslDaysHeader);
    if (!Number.isNaN(sslDays) && sslDays <= Number(meta.minSslDays || 14)) {
      reasons.push(`SSL certificate expires in ${sslDays} day(s)`);
    }
  }
  if (/cert|ssl|tls|expired/i.test(errorMsg)) {
    reasons.push(`TLS/SSL verification error: ${errorMsg.slice(0, 120)}`);
  }

  let matchedPrice = '';
  if (meta.pricePattern) {
    try {
      const rx = new RegExp(meta.pricePattern, 'i');
      const m = bodyStr.match(rx);
      if (m) {
        matchedPrice = m[0];
        if (meta.expectedPrice && matchedPrice !== meta.expectedPrice) {
          reasons.push(`Price/token changed: expected "${meta.expectedPrice}", got "${matchedPrice}"`);
        }
      } else if (meta.expectedPrice) {
        reasons.push('Price/token pattern not found in response body');
      }
    } catch (_err) {
      reasons.push('Invalid WATCH_PRICE_REGEX expression');
    }
  }

  const shouldAlert = reasons.length > 0;
  results.push({
    json: {
      url: meta.url,
      statusCode,
      elapsedMs,
      matchedPrice,
      reasons,
      shouldAlert,
      checkedAt: meta.checkedAt,
      alertText: [
        'WEBSITE UPTIME / SSL / PRICE ALERT',
        `URL: ${meta.url}`,
        `Status: HTTP ${statusCode || 'ERR'} (${elapsedMs}ms)`,
        `Issues: ${reasons.join('; ')}`,
        matchedPrice ? `Matched value: ${matchedPrice}` : 'Price watch: not triggered',
        `Checked at: ${meta.checkedAt}`
      ].join('\n')
    }
  });
}
return results;
